-- Triax vessels from printed pages 106-140.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzz-triax-vessels-p106-140.sql
--
-- BOOK-INGEST-AUDIT.md F3. The vessels were excluded from every batch of
-- this book because `gear` holds one mdc, one damage, one range and one
-- payload, and a vessel here has M.D.C. by LOCATION and several numbered
-- weapon systems with four stats each. Migration 048 gave them three tables
-- of their own - vehicles, vehicle_locations, vehicle_weapons - and this is
-- the data that was waiting on them.
--
-- A VESSEL BELONGS TO THE SLICE ITS NAME HEADING FALLS IN. That rule is why
-- no vessel is split across two of these files and none is imported twice:
-- a reader whose stat block runs past a page boundary read on to finish it,
-- and a reader who met a block already in progress skipped it.
--
-- INSERT OR IGNORE THROUGHOUT, and the readbacks COUNT rather than trusting
-- the exit code - an IGNORE that collides is silent, which is exactly how a
-- row goes missing without an error.
--
-- mdc_main_body is the main body ONLY. The full printed block is in
-- vehicle_locations, main body included, so it can be rendered in the order
-- the book sets it; a reader wanting a total must sum the rows.
--
-- A LOCATION WHOSE M.D.C. THE BOOK PRINTS AS A FORMULA carries mdc NULL and
-- the formula in mdc_note. The EIR-50 Gurgoyle Android is the whole reason:
-- its block is printed as dice, not numbers, because the machine is built to
-- match whatever gurgoyle it is imitating.

INSERT OR IGNORE INTO vehicles
  (slug, name, system, vehicle_class, crew, passengers, speed_ground,
   speed_air, speed_water, dimensions, weight_tons, mdc_main_body, cost,
   cost_note, description, source_book)
VALUES
('vx-500-manhunter', 'VX-500 Manhunter (Red Type)', 'rifts', 'borg', 'One human volunteer.', NULL, 'Running: 70 mph (112 km) in the standard heavy infantry armor or 100 mph (160 km) in light espionage armor. Leaping: 25 feet (7.6 m) high or lengthwise; a running leap adds 30 additional feet (9 m).', 'Via jet pack only; see the T-100 Eagle jet pack.', NULL, 'Average Height: 8 feet (2.4 m); Width: 4 feet (1.2 m); Length: 3 feet (0.9 m) is the length of the body itself, five feet (1.5 m) including the launch tubes.', '2000 lbs (900 kg)', 280, 6000000, 'Six to seven million credits with all standard features and weapons. Poor availability.', 'A full-conversion cyborg soldier of the NGR military, also called the "Red Type" for its usual color. A heavy-assault borg with mini-missile launch tubes, a rail gun, and concealed leg weapons.', 'Rifts World Book 5: Triax and the NGR p.106-108'),
('vx-635-prowler', 'VX-635 Prowler', 'rifts', 'borg', 'One human volunteer.', NULL, 'Running: 120 mph (192 km) maximum. Leaping: 20 feet (6 m) high or lengthwise; a running leap adds 30 feet (9 m). Thruster Assisted Leaps: four tiny concealed thrusters double the distance of a leap.', 'Via jet pack only.', NULL, 'Average Height: 6 feet 8 inches (2.0 m) from top of head to bottom of feet; telescoping surveillance eye adds an extra foot (0.3 m) retracted, three feet (0.9 m) fully extended. Width: 3 feet (0.9 m). Length: 2 feet (0.6 m).', '500 lbs (225 kg)', 180, NULL, 'Black Market Cost: Not available. Estimated worth: 50+ million credits just to study and knock off the VX-635 many unique bionic systems.', 'An intelligence/espionage full-conversion cyborg exclusive to NGR Special Forces. Carries concealed and experimental weapons and two brain implants for security.', 'Rifts World Book 5: Triax and the NGR p.108-113'),
('vx-2010-marauder', 'VX-2010 Marauder', 'rifts', 'borg', 'One human volunteer.', NULL, 'Running: 70 mph (112 km) maximum. Leaping: 25 feet (7.6 m) high or lengthwise, a running leap adds 30 feet (9 m). Jet Assisted Leaps: 150 feet (45.7 m) high or lengthwise maximum.', 'Via jet pack only, see the T-100 Eagle jet pack, but reduce flight speed by half due to the great weight and size of the borg.', NULL, 'Average Height: 9 feet (2.7 m). Width: 4 feet (1.2 m). Length: 3 feet (0.9 m).', '2800 lbs (1260 kg)', 660, 8000000, 'Black Market Cost: Not available on the open market. Rare, eight million credits with all standard features and weapons.', 'The first of the new VX-2000 series full-conversion cyborgs from Triax, a permanently armored heavy-assault borg with no separable body armor, larger, stronger and slower than earlier models, and able to inflict mega-damage bare-handed.', 'Rifts World Book 5: Triax and the NGR p.113-114'),
('vx-2020-monster', 'VX-2020 Monster', 'rifts', 'borg', 'One human volunteer.', NULL, 'Running: 70 mph (112 km) maximum. Leaping: 25 feet (7.6 m) high or lengthwise, a running leap adds 30 feet (9 m). Jet Assisted Leaps: 150 feet (45.7 m) high or lengthwise maximum.', 'Via jet pack only, see the T-100 Eagle jet pack, but reduce flight speed by half due to the great weight and size of the borg.', NULL, 'Average Height: 9 feet (2.7 m). Width: 4 feet (1.2 m). Length: 3 feet (0.9 m).', '3200 lbs (1440 kg)', 680, 8000000, 'Black Market Cost: Not available on the open market. Rare, eight million credits with all standard features and weapons.', 'A slightly more powerful variant of the VX-2010 Marauder, bigger and more heavily armored, fitted with an additional sensor array including a short-range radar system similar to those used in robots and power armor.', 'Rifts World Book 5: Triax and the NGR p.114-117'),
('xm-50-medic-ambulance-pod', 'XM-50 Medic Ambulance Pod', 'rifts', 'vehicle', 'One', 'Stretcher accommodates one prone patient or three sitting, in addition to the pilot.', NULL, 'Maximum flying speed 60 mph (96 km); cruising speed usually around 45 mph (76 km) and considerably slower when searching the battlefield. Can hover a few feet above the ground or up to 500 feet (152 m) in the air. With the force field active, maximum flight speed drops to 40 mph (64 km).', NULL, 'Height: 4 feet (1.2 m) from tail tip to the top of the windshield. Width: 3 feet six inches (1 m). Length: 6 feet (1.8 m), or 12 feet (3.6 m) with the stretcher extended.', '800 lbs (360 kg)', 140, 500000, 'Black Market Cost: 500,000 credits. Poor availability.', 'A small, speedy, one-man hover pod used by NGR medical field personnel to search the battlefield for the injured, extract them via an extendable stretcher, and carry medical supplies in five storage bays.', 'Rifts World Book 5: Triax and the NGR p.117-119'),
('xm-60-field-mechanic-pod', 'XM-60 Field Mechanic Pod', 'rifts', 'vehicle', 'One', NULL, NULL, 'Maximum flying speed 60 mph (96 km); cruising speed usually around 45 mph (76 km). Can hover a few feet above the ground or up to 500 feet (152 m) in the air.', NULL, 'Height: 4 feet (1.2 m) from tail tip to the top of the windshield. Width: 4 feet (1.2 m). Length: 7 feet (2.1 m), or 13 feet (3.9 m) with the storage rack extended.', '900 lbs (405 kg)', 160, 500000, 'Black Market Cost: 500,000 credits. Poor availability.', 'A field mechanic version of the XM-50 pod, slightly larger and heavier, trading the force field for stronger thrusters and a greater weight capacity for carrying salvaged or replacement parts.', 'Rifts World Book 5: Triax and the NGR p.119-120'),
('xm-70-covert-operations-pod', 'XM-70 Covert Operations Pod', 'rifts', 'vehicle', 'One', NULL, NULL, 'Maximum flying speed 100 mph (160 km); cruising speed usually around 45 mph (76 km) and considerably slower when prowling through enemy territory. Can hover a few feet above the ground or up to 600 feet (183 m) in the air.', NULL, 'Height: 4 feet (1.2 m) from tail tip to the top of the windshield. Width: 3 feet 6 inches (1 m). Length: 6 feet (1.8 m).', '800 lbs (360 kg)', 165, 800000, 'Black Market Cost: 800,000 credits. Poor availability.', 'An intelligence-operations variant of the pod line, designed with covert work in mind, no force field or signal beacon, replaced by rear boosters for additional speed and a mini-missile launcher.', 'Rifts World Book 5: Triax and the NGR p.119-120'),
('xm-140-infantry-support-weapon-platform', 'XM-140 Infantry Support Weapon Platform', 'rifts', 'vehicle', 'Four: One pilot, one co-pilot who also works communications, and two gunners. A fifth person to serve as an additional lookout and back-up crew member is common.', 'Can also accommodate six passengers if absolutely necessary, but conditions are cramped.', NULL, 'Maximum flying speed 50 mph (80 km); cruising speed usually around 35 mph (56 km) and considerably slower when prowling through enemy territory. Can hover a few feet above the ground or up to 1000 feet (183 m) in the air.', NULL, 'Shape: a somewhat oval disk shaped platform, slightly longer than it is wide. Height: main body roughly 6 feet (1.8 m) tall, with the long range missile launcher in its lowest position 8 feet (2.4 m) tall. Width: 18 feet (5.5 m). Length: 20 feet (6 m).', 'Five tons', 250, 1000000, 'Black Market Cost: One million credits, plus missile cost. Rare.', 'An open-top, flying troop assault and support vehicle used by the NGR military, dispatched against enemy ground and air troops and to support and extract friendly troops. Sacrifices speed for firepower and armor, mounting a long-range missile launcher, twin pulse lasers, rail guns and a rechargeable force field.', 'Rifts World Book 5: Triax and the NGR p.120-122'),
('xm-170-infantry-repair-barge', 'XM-170 Infantry Repair Barge', 'rifts', 'vehicle', '25: One pilot, one co-pilot, two communications officers, one gunner, plus 10 field mechanics and 10 assistants. An additional five mechanics, communication engineers or other soldiers may be added. There are 30 bunks for crew and mechanic staff.', 'In an emergency, the repair barge can transport as many as 120 foot soldiers, or 32 Jagers, or 10 Black Knights on its deck.', NULL, 'Maximum flying speed 45 mph (72 km); cruising speed usually around 25 mph (40 km). Can hover a few feet above the ground or up to 100 feet (30.5 m) in the air.', NULL, 'Shape: a long flatbed with a crew and repair section covering the front third of the vessel. Height: 40 feet (12.2 m) tall from the bottom of the hover jets to the top of the repair station, with the repair gantry 65 feet (19.8 m) total. Width: 60 feet (18.3 m). Length: 300 feet (91.5 m).', '114 tons', 600, NULL, 'Black Market Cost: Not available.', 'A heavily armored, mobile robot and vehicle repair station and troop carrier that operates in the field of combat, with its own repair gantry, mobile garage, storage area, and defensive laser and ion cannon turrets.', 'Rifts World Book 5: Triax and the NGR p.122-124'),
('xm-180-dragonfly', 'XM-180 Dragonfly Power Armor and Bot Drop Ship', 'rifts', 'vehicle', 'Four: One pilot, one co-pilot, one communications officer, and a gunner. The cockpit area can also accommodate four passengers comfortably.', 'Power Armor or Bot Payload: five Jager size units, four Super Jager sized units, or 10 man-sized units, 8 feet/2.4 m or smaller.', NULL, 'Mach 1.5, roughly 1005 mph/1608 km, maximum; cruising drop speed is usually a comparatively slow 300 mph (480 km). Maximum Altitude: 50,000 feet (15,240 m).', NULL, 'Height: 18 feet (5.5 m) tall. Width/Wingspan: 35 feet (10.7 m). Length: 65 feet (19.8 m).', '16 tons unloaded', 250, 1000000, 'Black Market Cost: One million credits, plus missile cost. Rare.', 'A fast, well-armed jet used to transport and parachute-drop bots and power armor troops into enemy territory; the paratrooper payload is typically five Jagers, five DV-40 combat bots, or four Super Jagers, released via rear carrying clamps.', 'Rifts World Book 5: Triax and the NGR p.123-125'),
('xm-250-medical-hover-station', 'XM-250 Medical Hover Station', 'rifts', 'vehicle', 'Five: One pilot, one co-pilot, one communications officer, and two gunners. The 28 medical personnel include eight surgeons, two cyber-docs, eight nurses, four orderlies/assistants, two chemists/laboratory techs, and four field medics.', '24 bed ridden patients and 24 ambulatory patients can be accommodated comfortably; an additional 24 people can be squeezed in during an emergency.', NULL, '140 mph (224 km) maximum; cruising speed usually around 50 mph (80 km). Maximum Altitude: 2000 feet (610 m).', NULL, 'Height: 25 feet (7.6 m) tall. Width/Wingspan: 26 feet (7.9 m). Length: 130 feet (39.6 m).', '129 tons fully loaded', 700, 15000000, 'Black Market Cost: a similarly styled vessel would cost something in the neighborhood of 15 to 20 million credits, plus medical equipment and crew.', 'A giant, mobile field hospital with eight surgical stations, a laboratory with refrigeration units, an x-ray machine, a quarantine chamber, hospital beds and bunks; carries defensive laser turrets used purely in self-defense.', 'Rifts World Book 5: Triax and the NGR p.125-126'),
('xm-270-mosquito', 'XM-270 Mosquito VTOL APC and Airship', 'rifts', 'vehicle', 'Five: One pilot, one co-pilot, one communications officer, and two gunners.', 'APC Troop Payload: 24 to 36 total, 12 man-sized comfortably per side compartment, 18 cramped.', NULL, 'Flying Conventional (Low Speed): hover stationary to 450 mph (up to 720 km). Flying Rocket Propelled (High Speed): Mach 2 to Mach 2.5, roughly 1340 to 1650 mph/2144 to 2655 km, via turbo overdrive; cannot regulate flight between 451 and 1340 mph. Maximum Altitude: 20,000 feet (6096 m) low speed or 50,000 feet (15,240 m) high speed.', NULL, 'Height: 20 feet (6 m). Width: 36 feet (10.9 m). Length: 75 feet (22.9 m).', '35 tons fully loaded', 900, NULL, 'Black market knock-offs cost 42 million credits and do NOT have the heavy ion cannons, typically replaced by lasers or rail guns. NGR issue cost not given.', 'A 22-year-old but still popular VTOL jet fighter/APC design, fully armored including the cockpit, with twin ion cannons, rapid-fire rail gun turrets, and a distinctive low-speed/high-speed-only flight envelope.', 'Rifts World Book 5: Triax and the NGR p.127-128'),
('xm-275-lightning', 'XM-275 Lightning VTOL Combat Jet', 'rifts', 'vehicle', 'Four: One pilot, one co-pilot, one communications officer, and a gunner.', 'APC Troop Payload: as many as 12 man-sized troops/passengers comfortably, 16 cramped.', NULL, 'Hover in stationary position, vertical movement, maximum speed Mach 2, roughly 1340 mph/2144 km. Maximum Altitude: 50,000 feet (15,240 m).', NULL, 'Height: 16 feet (4.8 m). Width: 40 feet (12.2 m). Length: 65 feet (19.8 m).', '14 tons fully loaded', 350, NULL, 'Black market knock-offs cost 40 million credits and do NOT have the Lightning Arc Charge Blaster, and seldom exceed Mach 1.5. NGR issue cost not given.', 'Triax high-tech successor to the 20th-Century helicopter, a fast, maneuverable VTOL combat jet named for its speed and its signature TX-275 Arc Charge Blaster, an electrical weapon that can disable enemy electronics.', 'Rifts World Book 5: Triax and the NGR p.128-130'),
('xm-280-fighter-jet', 'XM-280 Fighter Jet', 'rifts', 'vehicle', 'Two: One pilot and one co-pilot/bombardier.', 'APC Troop Payload: None.', NULL, 'A maximum speed of Mach 3, roughly 2010 mph/3216 km. Does not have the ability to hover or VTOL. Maximum Altitude: 60,000 feet (18,288 m).', NULL, 'Height: 15 feet (4.6 m). Width: 40 feet (12.2 m). Length: 70 feet (21.3 m).', '30 tons fully loaded', 300, NULL, 'Black Market Cost: Not available.', 'A traditional supersonic fighter and bomber capable of Mach 3, used against enemy strongholds and armored troops beyond NGR borders.', 'Rifts World Book 5: Triax and the NGR p.130-131'),
('xm-288-supersonic-transport', 'XM-288 Supersonic Transport', 'rifts', 'vehicle', 'Ten: Pilot, co-pilot, communications officer, three gunners, and four cargo maintenance laborers.', NULL, NULL, 'A maximum speed of Mach 4.5, roughly 3015 mph/4824 km. Does not have the ability to hover or VTOL. Maximum Altitude: 100,000 feet (30,500 m). Note: half the aircraft is devoted to engines and thrusters.', NULL, 'Height: overall belly to top of tail fin 120 feet (36.6 m), body only 80 feet (24.4 m). Width/Wingspan: 150 feet (45.7 m). Length: 500 feet (152.4 m).', '1000 tons unloaded', 200, NULL, 'Absolutely not available. Even the NGR only has six of these aircraft.', 'A supersonic, sub-orbital transport used to move vehicles, bots, power armor, weapons, supplies and raw materials between the NGR and the Coalition States, flying high enough to avoid most monster attacks and orbital hazards.', 'Rifts World Book 5: Triax and the NGR p.131-132'),
('xm-300-terror-mini-tank', 'XM-300 Terror Mini-Tank', 'rifts', 'vehicle', 'Two: One pilot and a gunner. One additional gunner, communications officer, or passenger can be accommodated.', NULL, '95 mph (152 km)', 'Flight is not possible.', '10 mph (16 km)', 'Height: 8 feet (2.4 m). Width: 6 feet (1.8 m). Length: 14 feet (4.2 m).', '3.5 tons fully loaded', 300, NULL, 'Black market knock-offs cost 40 million credits and may not have the same weapon systems.', 'A small but heavily armed two-to-three man tank, amphibious and suited to urban, grassland and light forest environments, named for the terror its firepower belies given its small size.', 'Rifts World Book 5: Triax and the NGR p.133-134'),
('xm-330-phantom-hover-tank', 'XM-330 Phantom Hover Tank', 'rifts', 'vehicle', 'Three: One pilot, a gunner and a communications officer. There are seats for two additional passengers and two others could squeeze in if they kneel, cramped.', 'Two seated comfortably, two more cramped.', '80 mph (128 km) maximum. The hover tank rides on a cushion of air as low as two feet (0.6 m) off the ground or as high as six feet (1.8 m).', 'Flight is not possible.', '15 mph (24 km)', 'Height: 9 feet (2.7 m). Width: 20 feet (6 m). Length: 35 feet (10.7 m).', '52 tons fully loaded', 700, NULL, 'Black market knock-offs cost 40 million credits and may not have the same weapon systems.', 'A quiet, all-terrain hover tank called the Phantom, moving on a cushion of air, giving it a base prowl of 35% in daylight and 60% in darkness; carries a double-barreled main cannon plus ion cannon, laser turret and mini-missiles.', 'Rifts World Book 5: Triax and the NGR p.134-135'),
('xm-350-leopard-iii-apc', 'XM-350 Leopard III APC', 'rifts', 'vehicle', 'Ten: One pilot, a co-pilot, communications officer, intelligence officer, and six gunners.', 'A standard infantry force includes: 20 to 28 foot soldiers, with or without jet packs; 4 X-10A Predators or X-535 or X-545 Jagers; 4 DV-12 Dyna-Bots, Super Troopers, or Glitter Boys; 2 DV-40 Combat Drones or X-2000 Dyna-Max; 2 field mechanics or commandos; 2 field medics; 1 XM-50 Medical Pod; 1 XM-300 Mini-Tank docked in the Terror Bay.', '80 mph (128 km)', 'Flight is not possible.', 'Not amphibious.', 'Height: 15 feet (4.6 m). Width: 12 feet (3.6 m). Length: 70 feet (21.3 m).', '89 tons unloaded', 900, NULL, 'Black market knock-offs cost 80 million credits and may not have the same weapon systems.', 'A giant APC and assault vehicle with a rear Terror Bay sized to carry and launch an XM-300 mini-tank, plus its own ion cannon, missile launchers, laser turrets and rail guns.', 'Rifts World Book 5: Triax and the NGR p.136-137'),
('mz-10-wilderness-crusader', 'Triax MZ-10 Wilderness Crusader', 'rifts', 'vehicle', 'One pilot and seats six passengers comfortably.', 'Six, comfortably.', 'Maximum Ground Speed: 160 mph (256 km). Hovers one to five feet above ground, 0.3 to 1.5 m.', NULL, 'Maximum Water Speed: 20 mph (32 km), amphibious.', 'Length: 9 feet (2.7 m). Height and Width are not given in the printed statistical data.', '1.2 tons', 310, 3500000, '3.5 million credits; good availability.', 'A civilian, all-terrain armored hover vehicle with a high-impact bumper, heavy armor and an ion weapon turret, popular for defense in the Monster Zones.', 'Rifts World Book 5: Triax and the NGR p.138'),
('wr-1010-land-rover', 'WR-1010 Land Rover', 'rifts', 'vehicle', 'One pilot; seats four passengers comfortably.', 'Four, comfortably.', 'Maximum Speed: 180 mph (288 km)', NULL, NULL, 'Length: 18 feet (5.5 m). Height and Width are not given in the printed statistical data.', '2 tons', 100, 28000, '28,000 credits; excellent availability.', 'A popular, balloon-tire, four-wheel-drive, all-terrain automobile used by wilderness folk, adventurers and bandits; inexpensive and low-maintenance.', 'Rifts World Book 5: Triax and the NGR p.138'),
('wr-2020-shark-bullet-bike', 'WR-2020 Shark Bullet Bike', 'rifts', 'vehicle', 'One pilot and seats one passenger comfortably.', 'One, comfortably; a mini-missile system, if fitted, removes the passenger seat.', 'Maximum Speed: 280 mph (448 km). -15% on piloting skill above 200 mph (321 km). Not amphibious. Jet Propelled Jumps: up to 50 feet (15.2 m).', NULL, NULL, 'Length: 9 feet (2.7 m). Height and Width are not given in the printed statistical data.', '1200 pounds (540 kg)', 80, 65000, '65,000 credits; excellent availability.', 'A rocket-shaped, jet-propelled hover cycle popular among city rats, wilderness scouts and bandits.', 'Rifts World Book 5: Triax and the NGR p.139'),
('wr-5050-super-cargo-hauler-apc', 'WR-5050 Super Cargo Hauler APC', 'rifts', 'vehicle', 'Three: Pilot, co-pilot, and gunner. Seats 12 passengers comfortably.', '12, comfortably.', 'Maximum Speed: 120 mph (192 km).', NULL, NULL, 'Height: 20 feet (6 m) for the main body, 32 feet including the rear bunk area, the printed metric conversion for that figure is garbled in the source, see flags. Width: 18 feet (5.4 m). Length: main body 60 feet (18.3 m), with the rear bunk area 80 feet (24.4 m) total.', '124 tons unloaded, can carry an additional 135 tons', 400, 45000000, '45 million credits; fair to good availability.', 'A gigantic all-terrain APC/cargo hauler used for hauling cargo, research, exploration, and personnel transport by corporations, scientific teams and wealthy adventurers outside the NGR.', 'Rifts World Book 5: Triax and the NGR p.139-140'),
('wr-5054-mini-cargo-hauler-apc', 'WR-5054 Mini-Cargo Hauler APC', 'rifts', 'vehicle', 'Three: Pilot, co-pilot, and gunner. Seats six passengers comfortably.', 'Six, comfortably.', 'Maximum Speed: 150 mph (240 km).', NULL, NULL, 'Height: 11 feet (3.3 m). Width: 7 feet (2.1 m). Length: 20 feet (6 m).', '5 tons unloaded, can carry an additional 10 tons', 200, 45000000, '45 million credits; fair to good availability. Printed identically to the WR-5050 Super cost line despite this being described as a much smaller vehicle, possibly a book error, transcribed as printed.', 'A smaller version of the WR-5050 Super Cargo Hauler, about a third its size and without the rear bunk compartment, with cargo space comparable to a full-size 20th-Century van.', 'Rifts World Book 5: Triax and the NGR p.140');

