INSERT OR IGNORE INTO vehicle_weapons
  (vehicle_slug, ordinal, name, damage, is_mega_damage, range,
   rate_of_fire, payload, bonus, note)
VALUES
('vx-500-manhunter', 1, 'TX-500 Triax Borg Rail Gun (1; standard issue)', 'A full burst is 30 rounds and inflicts 6D6 M.D. A half burst is 15 rounds and inflicts 3D6 M.D. One round does 1D4 M.D. Depleted uranium rounds adds an additional 2D6 M.D. to a full burst or 1D6 M.D. to a half burst.', 1, '4000 feet (1200 m)', 'One burst per hand to hand melee action/attack.', 'Heavy ammo-drum 1170 rounds (39 full 6D6 bursts), light drum/ammo-belt 390 rounds (13 full 6D6 bursts), or mini-clip 90 rounds (3 full bursts, 10 lbs/4.5 kg each).', '+1 to strike (telescopic, nightvision scope and laser targeting system)', 'Weight: Gun 80 lbs (36.3 kg), Power Pack 50 lbs (22.7 kg), light ammo-drum belt 25 lbs (11 kg), case of six light belts 150 lbs (67.5 kg). Market Cost: 85,000 credits. Fair availability.'),
('vx-500-manhunter', 2, 'VX-500 Mini-Missile Tube Launchers (6)', 'Varies with missile type; standard issue armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.). Fragmentation seldom used.', 1, 'Usually about a mile.', 'One at a time or volleys of two or three.', '12 total; two mini-missiles in each of six tubes.', NULL, 'Mounted on the back of the borg; anti-aircraft/defense purpose.'),
('vx-500-manhunter', 3, 'Concealed Leg Laser Rod (1; right hip)', '3D6 M.D. per blast.', 1, '3000 feet (914 m)', 'Equal to total number of hand to hand attacks.', '20 shots per E-clip.', NULL, 'Release, point and shoot.'),
('vx-500-manhunter', 4, 'Concealed Leg Ion Rod (1; left hip)', '4D6 M.D. per blast.', 1, '2000 feet (610 m)', 'Equal to total number of hand to hand attacks.', '20 shots per E-clip.', NULL, 'Release, point and shoot.'),
('vx-500-manhunter', 5, 'Hand to Hand Combat', 'Restrained Punch 1D6+15 S.D.C.; Full Strength Punch 4D6+15 S.D.C.; Power Punch 1D6 M.D. (counts as 2 melee attacks); Head Butt 2D6 S.D.C.; Kick 4D6+15 S.D.C.; Jump Kick/Leap Attack 2D6 M.D. (counts as 2 melee attacks); Judo Style Throw/Flip 3D6 S.D.C.; Full Speed Ram/Body Block 1D4 M.D. (counts as 2 melee attacks); Garrote Strangle Attack 4D6+15 S.D.C. plus 3D6 S.D.C. per tightening movement/attack.', 1, 'Melee', NULL, NULL, '+1 initiative, +2 pull punch, +1 save vs horror factor; P.P. 22 bonus: +4 strike/parry/dodge.', 'Attacks per melee = hand to hand skill selection/experience plus one additional attack from heightened reflexes.'),
('vx-635-prowler', 1, 'VX-635 Multi-Weapon Gun-Arm (1, standard issue)', 'A) Rail Gun: full burst 20 rounds = 4D6 M.D.; single round = 2 M.D.; may fire DU-rounds (5D6 M.D.) or U-rounds (5D6 M.D., plus diminishes healing in supernatural beings). B) Vibro-Bayonet: 2D6 M.D. per strike as vibro-sword/bayonet or 6D6 M.D. fired once as a rocket projectile. C) Mini-Laser Turret: 3D6 M.D. per blast. D) Utility Arms (2): no mega-damage; a punch does 1D6 S.D.C.', 1, 'A) 4000 feet (1200 m). B) 300 feet (91.5 m) as a projectile. C) 3000 feet (910 m). D) three feet (0.9 m) reach.', 'A) equal to hand to hand attacks per melee round, usually 4-6. B) same as any sword, or once as a projectile. C) equal to total hand to hand attacks. D) adds one melee action when used.', 'A) short clip 200 rounds/10 bursts; 2000-round drum 100 bursts. C) effectively unlimited.', 'B) +1 to strike and parry. C) +1 to strike.', 'Right forearm multi-weapon system; can be replaced by a mechanical human-like arm or other weapon arm.'),
('vx-635-prowler', 2, 'Launchable Shoulder Spikes (12)', 'One M.D. per spike.', 1, '200 feet (61 m)', 'One at a time or volleys of two, four, eight or 12; a volley counts as one melee attack.', '12', '-1 to strike, penalty', 'Right shoulder covered in 2-4 inch spikes; secondary purpose is to create a distraction.'),
('vx-635-prowler', 3, 'VX-635 Pneumatic Air Gun (1)', 'None; one S.D.C. point structurally. A) Dart-Sleep: knocks out target in 1D4 melee rounds, unconscious 4D6 minutes, only 1D4 melee rounds if save vs toxin succeeds; not effective vs mega-damage creatures. B) Dart-Poison: 1D6x10 S.D.C. after one melee round, half on save; not effective vs mega-damage creatures. C) Surveillance-Mini-Microphone: no damage. D) Surveillance-Homing device: no damage.', 0, '200 feet (61 m); 500 feet (152 m) maximum, -3 to strike beyond 200 feet. C) transmission range 1000 feet (305 m), 24 hrs. D) transmission range 2000 feet (609 m), 48 hrs.', 'As many as two per melee action.', '12 of each type.', NULL, 'Mounted next to the right shoulder; mostly non-lethal surveillance turret.'),
('vx-635-prowler', 4, 'Head Mounted Mini-Lasers (1 pair)', 'Two settings: 1D6x10 S.D.C. or 1D6 M.D. per single blast; both lasers fired simultaneously at the same target, aimed shot only, inflict double damage.', 1, '2000 feet (610 m)', 'Equal to total number of hand to hand attacks.', 'Effectively unlimited.', '+1 to strike', 'Mounted on top of the head; used as tool or weapon.'),
('vx-635-prowler', 5, 'Pneumatic Blade Shooter (1)', '3D4 S.D.C. per single blade, or 1D6x10+10 S.D.C. per poison-coated blade, half poison damage on save but full +10 S.D.C. from blade still applies; not effective vs mega-damage creatures.', 0, '200 feet (61 m); 500 feet (152 m) maximum, -3 to strike beyond 200 feet.', 'One at a time or rapid-fire volleys of two, counts as one melee action.', '24 blades, poisoned or not.', NULL, 'Used primarily against S.D.C. creatures such as humans and many D-bees.'),
('vx-635-prowler', 6, 'RVB-31 Vibro-Blade (1)', '2D4 M.D.', 1, 'Hand to hand combat.', NULL, NULL, NULL, 'Standard vibro-blade short sword concealed in a housing in the left forearm.'),
('vx-635-prowler', 8, 'VX-635 Ring Lasers (2)', '1D6 M.D. per blast.', 1, '1000 feet (305 m)', 'Equal to total number of hand to hand attacks.', 'Effectively unlimited.', NULL, 'Each leg has a tiny, rotating laser that can swivel 180 degrees.'),
('vx-635-prowler', 10, 'VX-635 Close Contact Spray (2)', 'Varies from none to little per spray.', 0, '20 feet (6 m)', 'Equal to total number of hand to hand attacks.', '20 total; ten per each nozzle.', NULL, 'Two circular nozzles in the chest spray tear gas/mace, acid, or water, against vampires.'),
('vx-635-prowler', 12, 'Hand to Hand Combat', 'Restrained Punch 1D6+9 S.D.C.; Full Strength Punch 3D6+9 S.D.C.; Power Punch 1D4 M.D., counts as 2 melee attacks; Power Stab with Vibro-Blade 3D6 M.D., counts as 2 melee attacks; Power Stab with Vibro-Bayonet 6D6 M.D., counts as 2 melee attacks; Head Butt 2D6 S.D.C.; Kick 3D6+9 S.D.C.; Jump Kick/Leap Attack 1D6 M.D., counts as 2 melee attacks; Judo style throw/flip 2D6 S.D.C.', 1, 'Melee', NULL, NULL, '+7 to strike, parry and dodge; one additional attack/action per melee round; cannot be surprised from behind; +5 initiative, +3 pull punch, +4 roll with impact, +1 save vs psionic attack, +1 save vs horror factor.', NULL),
('vx-2010-marauder', 1, 'TX-42 Laser Pulse Rifle', '2D6 M.D. per single shot or 1D4x10 M.D. per rapid-fire pulse, three nearly simultaneous blasts fired one micro-second apart.', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks.', '40 total, a large energy clip in the front of the gun, plus a second E-clip concealed in a secret chest compartment.', NULL, 'Variable light frequency laser with 12 settings, changed by touch or voice command; setting 7 counters the USA-10 Glitter Boy. Large/strong enough to use the giant TX-41 as a two-handed rifle.'),
('vx-2010-marauder', 2, 'VX-20 Grenade Launcher (1)', 'Varies; fragmentation 2D6 M.D. to a 20 foot/6 m radius, plasma 5D6 M.D. covering a 12 foot/3.6 m diameter, smoke has no damage, or riot control/tear gas/stun.', 1, '300 feet (91.5 m)', 'One at a time or in volleys of two or three fired in rapid succession.', '48 total; typically 2 smoke, 4 tear gas, 22 plasma and 20 fragmentation.', NULL, 'Mounted on the left side of the neck collar.'),
('vx-2010-marauder', 3, 'VX-2000 Concealed Ion Blasters (2)', '4D6 M.D. per single blast or 1D4x10+6 per twin blasts.', 1, '1000 feet (305 m)', 'Equal to the total number of hand to hand attacks.', 'Effectively unlimited, patched into the power supply of the borg.', NULL, 'Heavy chest plates slide open to reveal a pair of heavy-duty, short-range ion blasters.'),
('vx-2010-marauder', 4, 'Concealed Leg Laser Rod (1; right leg)', '3D6 M.D. per blast.', 1, '3000 feet (914 m)', 'Equal to the total number of hand to hand attacks.', 'Effectively unlimited, patched into the power supply of the borg.', NULL, 'Release, point and shoot.'),
('vx-2010-marauder', 5, 'Concealed Vibro-Blades (2)', '2D6 M.D.', 1, 'Hand to hand combat.', NULL, NULL, NULL, 'A large vibro-sword is concealed in a housing in each arm.'),
('vx-2010-marauder', 7, 'Hand to Hand Combat', 'Restrained Punch 1D6+25 S.D.C.; Full Strength Punch 1D6 M.D.; Power Punch 2D6 M.D., counts as 2 melee attacks; Head Butt 1D4 M.D.; Kick 1D6 M.D.; Jump Kick/Leap Attack 2D6 M.D., counts as 2 melee attacks; Judo Style Throw/Flip 1D4 M.D.; Full Speed Ram/Body Block 1D4 M.D., counts as 2 melee attacks.', 1, 'Melee', NULL, NULL, '+4 to strike and parry, +3 to dodge, +1 initiative, +2 pull punch, +2 roll with impact, +1 save vs psionic attack, +1 save vs horror factor, includes P.P. 21 bonus and optic/sensor considerations.', 'Unlike the typical borg, including the VX-500, the 2000 series can inflict mega-damage from punches and kicks.'),
('vx-2020-monster', 1, 'TX-50 Rail gun (1)', 'A full damage burst fires 20 rounds and inflicts 4D6 M.D., a single round does 1D4 M.D.', 1, '4000 feet (1200 m)', 'Equal to the hand to hand attacks per melee round, usually 3 to 6.', 'Short clip 200 rounds/10 bursts; light drum 600 rounds/30 bursts; 2000-round heavy drum 100 bursts.', '+1 to strike, human-troop version has its own laser targeting/telescopic sight/nightvision scope, range 6000 feet/1828 m.', 'Standard issue is a heavy belt-feed drum, 2000 rounds/100 bursts.'),
('vx-2020-monster', 2, 'Mini-Missile Tube Launchers (18)', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D. Fragmentation seldom used.', 1, 'Usually about a mile.', 'One at a time or volleys of two, three or four.', '18 total, five on each shoulder and four on each leg.', NULL, 'Mounted on the shoulders and lower legs.'),
('vx-2020-monster', 3, 'VX-2000 Concealed Ion Blasters (2)', '4D6 M.D. per single blast or 1D4x10+6 per twin blasts.', 1, '1000 feet (305 m)', 'Equal to the total number of hand to hand attacks.', 'Effectively unlimited, patched into the power supply of the borg.', NULL, 'Heavy chest plates slide open to reveal a pair of heavy-duty, short-range ion blasters.'),
('vx-2020-monster', 4, 'VX-270 Concealed Particle Beam Weapon Rod (1, standard issue)', '6D6+6 M.D. per blast.', 1, '1000 feet (305 m)', 'Equal to the total number of hand to hand attacks per melee.', '36 shots; although patched into the power supply of the borg, the powerful beam draws a great amount of energy and recharges at a rate of 8 blasts per hour.', NULL, 'Right or left leg contains a concealed particle beam weapon similar to the arm weapon in the VX-370.'),
('vx-2020-monster', 5, 'Concealed Vibro-Blades (2)', '2D6 M.D.', 1, 'Hand to hand combat.', NULL, NULL, NULL, 'A large vibro-sword is concealed in a housing in each arm.'),
('vx-2020-monster', 7, 'Hand to Hand Combat', 'Restrained Punch 1D6+25 S.D.C.; Full Strength Punch 1D6 M.D.; Power Punch 2D6 M.D., counts as 2 melee attacks; Head Butt 1D4 M.D.; Kick 1D6 M.D.; Jump Kick/Leap Attack 2D6 M.D., counts as 2 melee attacks; Judo Style Throw/Flip 1D4 M.D.; Full Speed Ram/Body Block 1D4 M.D., counts as 2 melee attacks.', 1, 'Melee', NULL, NULL, '+5 to strike, +4 to parry and dodge, +3 initiative, +2 pull punch, +2 roll with impact, +1 save vs psionic attack, +1 save vs horror factor, includes P.P. 21 bonus; cannot be surprised by attacks from behind.', NULL),
('xm-50-medic-ambulance-pod', 2, 'Mini-Laser Defense Turret (1)', '2D6 M.D. per blast', 1, '1200 feet (366 m)', 'Usually set on automatic defense and firing five times per melee round.', 'Effectively unlimited.', NULL, 'Located in the rear of the pod behind the driver seat; especially effective against missile attacks and to deter attacks from behind.'),
('xm-60-field-mechanic-pod', 1, 'Pulse Laser Turret (1)', '2D6 M.D. per single blast or 6D6 per triple pulse, the pulse counts as one melee action.', 1, '2000 feet (610 m)', 'Equal to the pilot attacks/actions per melee.', 'Effectively unlimited.', NULL, 'Turret rotates 360 degrees and the weapon barrel raises/lowers 45 degrees.'),
('xm-60-field-mechanic-pod', 2, 'Rear Laser Turret (1)', '2D6 M.D. per blast', 1, '1200 feet (366 m)', 'Usually set on automatic defense and firing five times per melee round.', 'Effectively unlimited.', NULL, 'Located rear of the pod behind the driver seat; especially effective against missile attacks and to deter attacks from behind.'),
('xm-70-covert-operations-pod', 1, 'Pulse Laser Turret (1)', '2D6 M.D. per single blast or 6D6 per triple pulse, the pulse counts as one melee action.', 1, '2000 feet (610 m)', 'Equal to the pilot attacks/actions per melee.', 'Effectively unlimited.', NULL, 'Turret rotates 360 degrees and the weapon barrel raises/lowers 45 degrees.'),
('xm-70-covert-operations-pod', 2, 'Rear Laser Turret (1)', '2D6 M.D. per blast', 1, '1200 feet (366 m)', 'Usually set on automatic defense and firing five times per melee round.', 'Effectively unlimited.', NULL, 'Located rear of the pod behind the driver seat.'),
('xm-70-covert-operations-pod', 3, 'Mini-Missile Launcher', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D. Fragmentation used for anti-personnel operations.', 1, 'Usually about a mile.', 'One or a volley of two or three.', 'Six', NULL, 'The center storage bay has been converted into a small mini-missile launcher.'),
('xm-140-infantry-support-weapon-platform', 1, 'Long Range Missile Launcher (1)', 'Varies with missile type; typically a plasma, proton or nuclear smart bomb warhead, +5 to strike.', 1, 'Varies, 500 to 1800 miles (804 to 2893 km).', 'One', 'One', NULL, 'Can also fire medium range missiles; typically operated by the pilot or co-pilot; launch housing angles up/down 45 degrees.'),
('xm-140-infantry-support-weapon-platform', 2, 'Concealed Mini-Missile Launcher', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D. Fragmentation used for anti-personnel operations.', 1, 'Usually about a mile.', 'One or a volley of two or three.', '12', NULL, 'Underneath the long range missile launcher housing; typically operated by the pilot or co-pilot.'),
('xm-140-infantry-support-weapon-platform', 3, 'Twin Pulse Laser Turrets (2)', '2D6 M.D. per single blast or 6D6 per triple pulse, counts as one melee action; both turrets simultaneously inflict 1D6x10+6 M.D., counts as one melee action.', 1, '2000 feet (610 m)', 'Equal to the pilot attacks/actions per melee.', 'Effectively unlimited.', NULL, 'Located in the lower, front section; operated by pilot or co-pilot.'),
('xm-140-infantry-support-weapon-platform', 4, 'Light Rail Guns (2; mini-gun style)', 'A full damage burst fires 30 rounds and inflicts 6D6 M.D.; a quick burst fires 15 rounds and inflicts 3D6 M.D.; a single round does one M.D. point.', 1, '4000 feet (1200 m)', 'Equal to the character hand to hand attacks per melee round, usually 3 to 6.', '9000 rounds, 300 full bursts, belt fed from a massive ammo-drum in the hull; 20 minutes to reload by an experienced field mechanic.', '+1 to strike, own laser targeting system, telescopic sight and nightvision scope, range 6000 feet/1828 m.', 'Manned by a gunner in cyclops body armor at each of two gunner stations; DU-Rounds or U-Rounds can be substituted.'),
('xm-170-infantry-repair-barge', 1, 'Twin Forward Laser Turrets (2)', '5D6 M.D. per single blast; both turrets simultaneously inflict 1D6x10 M.D., counts as one melee action.', 1, '2000 feet (610 m)', 'Equal to the pilot attacks/actions per melee.', 'Effectively unlimited.', NULL, 'On top of the forward section; operated by pilot or co-pilot.'),
('xm-170-infantry-repair-barge', 2, 'Lower Forward Laser Turret (1)', '5D6 per blast.', 1, '4000 feet (1200 m)', 'Equal to the pilot attacks/actions per melee.', 'Effectively unlimited.', NULL, 'Long-range cannon on the underbelly of the forward section.'),
('xm-170-infantry-repair-barge', 3, 'Twin Rear Weapon Turrets (2)', '1D4x10 per single blast; both turrets simultaneously inflict 2D4x10 M.D., counts as one melee action.', 1, '3000 feet (914 m)', 'Equal to the gunner attacks/actions per melee.', 'Effectively unlimited.', NULL, 'Long-range ion cannons housed in armored turrets in the tail; also help protect the barge deck and personnel from rear fire.'),
('xm-170-infantry-repair-barge', 4, 'Concealed Mini-Missile Launcher', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D. Fragmentation used for anti-personnel operations.', 1, 'Usually about a mile.', 'One or a volley of two or three.', '32', NULL, 'On top of the pilot section; typically operated by the gunner or co-pilot.'),
('xm-180-dragonfly', 1, 'Medium Range Missile Launcher (2)', 'Varies with missile type; typically a plasma, high explosive heavy, or multi-warhead.', 1, 'Varies, 40 to 80 miles (64 to 128 km).', 'One', 'Two; one on each wing tip.', NULL, 'Typically operated by the gunner.'),
('xm-180-dragonfly', 2, 'Wing Mini-Missiles (16)', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D. Fragmentation used for anti-personnel operations.', 1, 'Usually about a mile.', 'One at a time or a volley of two, three or four.', '16 total, eight on each wing.', NULL, 'Two rows of four mini-missiles underneath each wing; typically controlled by gunner or co-pilot.'),
('xm-180-dragonfly', 3, 'Nose Gun (light rail gun; 1)', 'A full damage burst fires 30 rounds and inflicts 6D6 M.D.', 1, '4000 feet (1200 m)', 'Equal to the pilot hand to hand attacks per melee round, usually 3 to 6.', '6000 rounds, 200 full bursts, fed from a massive ammo-drum in the nose; 20 minutes to reload by an experienced field mechanic.', '+1 to strike.', 'Double-barrel rail gun turret on the front of the nose; typically controlled by the pilot.'),
('xm-180-dragonfly', 4, 'Double-barrelled Laser Turret (1)', '3D6 M.D. per single blast or 6D6 per double blast.', 1, '4000 feet (1200 m)', 'Equal to the gunner attacks/actions per melee round, typically 3 to 6.', 'Effectively unlimited.', NULL, 'On top of the Dragonfly to fight aerial attackers and counter enemy missiles; typically operated by the gunner.'),
('xm-180-dragonfly', 5, 'Anti-Missile Chaff Dispenser (1)', 'None; roll percentile dice: 01-50 enemy missile/volley detonates in the chaff cloud; 51-75 missile/volley loses track and veers away, may lock onto another aircraft; 76-00 no effect. Also temporarily blinds gargoyles/flying monsters passing through it, halves attacks/bonuses/speed for 1D4 melee rounds.', 0, NULL, NULL, 'Six', NULL, 'Located in the tail end of the combat jet.'),
('xm-250-medical-hover-station', 1, 'Forward Weapon Turret: Long-range Pulse Laser Cannon (1)', '2D6 M.D. per single blast or 6D6 per triple pulse, counts as one melee action.', 1, '4000 feet (1200 m)', 'Equal to the pilot attacks/actions per melee.', 'Effectively unlimited.', NULL, 'Single barrel turret on top of the cockpit; typically operated by the co-pilot.'),
('xm-250-medical-hover-station', 2, 'Middle Weapon Turrets: Long-range Pulse Laser Cannons (2)', '2D6 M.D. per single blast or 6D6 per triple pulse; both turrets simultaneously inflict 1D6x10+6 M.D., counts as one melee action.', 1, '4000 feet (1200 m)', 'Equal to the gunner attacks/actions per melee.', 'Effectively unlimited.', NULL, 'On top of the medical station near the midsection; typically operated by the gunner.'),
('xm-250-medical-hover-station', 3, 'Single Barrel Laser Turrets (2)', '3D6 M.D. per single blast or 6D6 per simultaneous blast from both turrets firing at the same target.', 1, '2000 feet (614 m)', 'Equal to the gunner attacks/actions per melee round, typically 3 to 6.', 'Effectively unlimited.', NULL, 'On top of the station toward the rear; smaller/shorter range, designed mainly as anti-missile; operated by gunner or communications officer.'),
('xm-270-mosquito', 1, 'Nose Laser (1)', '5D6 M.D. per blast.', 1, '4000 feet (1200 m)', 'Equal to the operator hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', '+1 to strike.', NULL),
('xm-270-mosquito', 2, 'Rail Gun Turrets (2)', 'A burst fires 30 rounds and inflicts 1D4x10 M.D.; single rounds cannot be fired; synchronized attack from both turrets inflicts 2D4x10 M.D.', 1, '4000 feet (1200 m)', 'Equal to hand to hand attacks per melee round, usually 3 to 6, plus one.', '9000 rounds, 300 full bursts, fed from a massive ammo-drum in the hull; 20 minutes to reload by an experienced field mechanic.', NULL, NULL),
('xm-270-mosquito', 3, 'High-Powered Ion Cannons (2)', '1D4x10 M.D. per single blast or 2D4x10 per simultaneous blasts from each at same target.', 1, '3000 feet (914 m)', 'Equal to the gunner hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', '+1 to strike.', NULL),
('xm-270-mosquito', 4, 'Mini-Missile Side Launchers (10)', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.', 1, 'Usually about a mile.', 'One at a time or a volley of two, three or four.', '20 total, ten in each side, two per compartment.', NULL, NULL),
('xm-270-mosquito', 5, 'Anti-Missile Chaff Dispenser (1)', 'None; percentile roll, see the XM-180 description.', 0, NULL, NULL, 'Four', NULL, NULL),
('xm-275-lightning', 1, 'Nose Laser (1)', '5D6 M.D. per blast.', 1, '4000 feet (1200 m)', 'Equal to the gunner hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', '+1 to strike.', NULL),
('xm-275-lightning', 2, 'TX-275 Lightning Arc Charge Blaster (2)', '6D6 M.D. per single blast, plus an electrical-system disruption effect on the enemy craft, roll percentile: 01-15 none; 16-30 minor blackout/lost action; 31-45 all weapons out 1D4 melee rounds; 46-60 all systems out 1D4 melee rounds, -30% piloting; 61-75 comms/radar/targeting fried, -3 to strike, no initiative; 76-90 instrument panel fried, escalating piloting penalties, no initiative, -3 dodge, -3 strike, lose one action; 91-00 all systems locked, craft crashes in 2D4 minutes. Living creatures lose one melee action/initiative; some supernatural beings take double damage from electricity.', 1, '2000 feet (610 m)', 'Maximum of four blasts per melee, two per gun.', 'Effectively unlimited.', '+1 to strike.', 'Pilot must roll under piloting skill to avoid catching part of the blast when firing; if struck, damage/penalties/durations are halved.'),
('xm-275-lightning', 3, 'Anti-Missile Chaff Dispenser (1)', 'None; percentile roll, see the XM-270 description.', 0, NULL, NULL, 'Four', NULL, NULL),
('xm-280-fighter-jet', 1, 'Nose Lasers (2)', '4D6 M.D. per single blast or 1D4x10+6 per double blast.', 1, '2000 feet (610 m)', 'Equal to the pilot hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', NULL, NULL),
('xm-280-fighter-jet', 2, 'Bomb Payload (16)', 'High explosive: 3D4x10 M.D. per bomb. Plasma: 3D6x10 per bomb, plus 90% chance of fires. Nuclear: 4D6x10 per bomb.', 1, 'Dropped from as low as 1000 feet, +1 to strike, or as high as 20,000 feet, -2 to strike.', 'A volley of four, eight or 16 at a time.', '16 total.', NULL, 'Area effect from a four-bomb volley typically 300 feet (91.5 m).'),
('xm-280-fighter-jet', 3, 'Wing Mini-Missiles (8)', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.', 1, 'Usually about a mile.', 'One at a time or in volleys of two, three or four.', '8 total, four on each wing.', NULL, NULL),
('xm-280-fighter-jet', 4, 'Anti-Missile Chaff Dispenser (1)', 'None; see description under XM-270 or XM-275.', 0, NULL, NULL, 'Four', NULL, NULL),
('xm-288-supersonic-transport', 1, 'Medium Range Missile Launchers (2)', 'Any medium range missile; typically plasma 2D6x10 M.D. or multi-warhead 2D4x10 M.D., smart bombs, +5 to strike.', 1, 'Typically 40 to 80 miles (64 to 128 km).', 'One or two at a time.', '12', NULL, 'Two concealed missile launchers housed in the top of the aircraft in front of the weapon turret.'),
('xm-288-supersonic-transport', 2, 'Pulse Laser Turrets (3, per weapon-systems text; M.D.C. table prints 2, see flags)', '2D6 M.D. per single blast or 6D6 per triple pulse; the two bottom turrets simultaneously inflict 1D6x10+6 M.D.', 1, '2000 feet (610 m)', 'Equal to the gunner attacks/actions per melee.', 'Effectively unlimited.', NULL, 'One turret on top toward the front, one directly below on the belly, and another on the belly toward the rear per the prose description.'),
('xm-288-supersonic-transport', 3, 'Anti-Missile Chaff Dispenser (1)', 'None; see description under XM-270 or XM-275.', 0, NULL, NULL, '12', NULL, NULL),
('xm-300-terror-mini-tank', 1, 'High-Powered Ion Cannon (1)', '1D4x10 M.D. per blast.', 1, '3000 feet (914 m)', 'Equal to the gunner hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', '+1 to strike.', NULL),
('xm-300-terror-mini-tank', 2, 'Laser Gun (1)', '4D6 M.D. per blast.', 1, '2000 feet (610 m)', 'Equal to the operator hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', NULL, 'Manually operated like a machine gun through an access hatch below the gun.'),
('xm-300-terror-mini-tank', 3, 'Forward Rail Gun Turrets (2)', 'A burst fires 30 rounds and inflicts 1D4x10 M.D.; single rounds cannot be fired; synchronized attack from both turrets inflicts 2D4x10 M.D.', 1, '4000 feet (1200 m)', 'Equal to hand to hand attacks per melee round, usually 3 to 6, plus one.', '12,000 rounds, 400 bursts total, 6000 rounds/200 bursts per turret, fed from a massive ammo-drum in the hull; 10 minutes to reload by field mechanic.', NULL, NULL),
('xm-300-terror-mini-tank', 4, 'Dual Mini-Missile Launcher (1)', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.', 1, 'Usually about a mile.', 'One at a time or a volley of two, three or four.', '20 total, ten in each side.', NULL, NULL),
('xm-300-terror-mini-tank', 5, 'Flamethrowers (2)', '1D4 M.D. per single blast or 2D4 per simultaneous double blast of napalm-like fire, plus 01-90% chance of setting combustible material on fire, additional 1D4 M.D. per melee round, burns minimum 2D4 minutes.', 1, '200 feet (61 m)', 'Equal to number of combined hand to hand attacks, usually 4-8.', '24 blasts total, 12 from each turret.', NULL, NULL),
('xm-330-phantom-hover-tank', 1, 'Main Gun: Double-barreled Cannon (1)', 'Particle Beam Cannon: 2D4x10 M.D. per single blast. Laser Cannon: 1D4x10 M.D. per blast; simultaneous blast from both cannons at the same target does 3D4x10.', 1, 'Particle Beam Cannon 3000 feet (914 m); Laser Cannon 4000 feet (1200 m).', 'Particle Beam: equal to number of combined hand to hand attacks, usually 3-6. Laser: equal to the gunner hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', NULL, 'The larger barrel fires a particle beam, the smaller barrel underneath fires a long-range laser; the entire turret can rotate 360 degrees and the barrels raise 45 degrees.'),
('xm-330-phantom-hover-tank', 2, 'Ion Cannon (1)', '1D4x10 M.D. per blast.', 1, '2000 feet (610 m)', 'Equal to the gunner hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', NULL, 'Stubby barrel in the center of the weapon turret; short range.'),
('xm-330-phantom-hover-tank', 3, 'Forward Rail Gun Turrets (2)', 'A burst fires 30 rounds and inflicts 1D4x10 M.D.; single rounds cannot be fired; synchronized attack from both turrets inflicts 2D4x10 M.D.', 1, '4000 feet (1200 m)', 'Equal to hand to hand attacks per melee round, usually 3 to 6, plus one.', '12,000 rounds, 400 bursts total, 6000 rounds/200 bursts per turret; 10 minutes to reload by field mechanic.', NULL, NULL),
('xm-330-phantom-hover-tank', 4, 'Low Profile Laser Turret', '3D6 M.D. per blast.', 1, '1200 feet (488 m)', 'Equal to that of the gunner.', 'Effectively unlimited.', NULL, 'Small, flat, disk-like turret at the rear top area of the main turret; rotates 360 degrees.'),
('xm-330-phantom-hover-tank', 5, 'Mini-Missile Launchers (2)', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.', 1, 'Usually about a mile.', 'One at a time or a volley of two, or three.', '12 total, six in each launcher.', NULL, NULL),
('xm-330-phantom-hover-tank', 6, 'Smoke Grenade Launchers (3)', 'None; used to create cover, same stats as the smoke grenade used by the X-60 Flanker.', 0, NULL, NULL, 'Three', NULL, NULL),
('xm-350-leopard-iii-apc', 1, 'High-Powered, Double-barreled Ion Cannon (1)', '1D4x10 M.D. per single blast or 2D4x10 M.D. per simultaneous double blast at same target.', 1, '3000 feet (914 m)', 'Equal to the gunner hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', '+1 to strike.', 'The entire turret, which includes a sensor disk and man operated laser gun, can turn 360 degrees; the cannon can be raised in a 45 degree arc of fire.'),
('xm-350-leopard-iii-apc', 2, 'Medium Range Missile Launchers (2)', 'Any medium range missile; typically plasma 2D6x10 M.D. or multi-warhead 2D4x10 M.D.', 1, 'Varies, 40 to 80 miles.', 'One at a time or in volleys of two, three or four.', '16 total, eight per launcher.', NULL, 'On the back of the ion cannon turret, both fixed forward; missiles are heat seeking, +3 to strike, or smart bombs, +5 to strike.'),
('xm-350-leopard-iii-apc', 3, 'Pulse Laser Turrets (4)', '2D6 M.D. per single blast or 6D6 per triple pulse; the two front turrets simultaneously inflict 1D6x10+6 M.D.', 1, '2000 feet (610 m)', 'Equal to the pilot attacks/actions per melee.', 'Effectively unlimited.', NULL, 'A pair on the forward section, two more about 10 feet (3 m) behind and to the side of the forward pair.'),
('xm-350-leopard-iii-apc', 4, 'Manned Laser Guns (2)', '4D6 M.D. per blast.', 1, '2000 feet (610 m)', 'Equal to the operator hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', NULL, 'One mounted at the forward hatch on the main turret above the ion cannons, another near the top hatch of the crew compartment.'),
('xm-350-leopard-iii-apc', 5, 'Side Rail Gun Turrets (2)', 'A burst fires 30 rounds and inflicts 1D4x10 M.D.; single rounds cannot be fired.', 1, '4000 feet (1200 m)', 'Equal to hand to hand attacks per melee round, usually 3 to 6, plus one.', '12,000 rounds, 400 bursts total, 6000 rounds/200 bursts per turret; 15 minutes to reload by field mechanic.', NULL, 'Above each of the large side hatches where troops disembark.'),
('xm-350-leopard-iii-apc', 6, 'Smoke Grenade Launchers (8)', 'None; used to create cover, same stats as the smoke grenade used by the X-60 Flanker.', 0, NULL, NULL, '8; four on each side of the main turret.', NULL, NULL),
('mz-10-wilderness-crusader', 1, 'Standard Weapon: Ion Cannon', '6D6 M.D. per single blast; a mechanic could upgrade to 1D4x10 M.D. with a 3000 foot range.', 1, '2000 feet (610 m)', 'Equal to the gunner hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', '+1 to strike.', 'Turret includes sensors/laser targeting, rotates 360 degrees, barrel raises 45 degrees; typically controlled by the driver or a passenger.'),
('wr-5050-super-cargo-hauler-apc', 1, 'Standard Weapon: Forward Laser Turret', '3D6 M.D. per single blast.', 1, '2000 feet (610 m)', 'Equal to the gunner hand to hand attacks per melee round, usually 3 to 6.', 'Effectively unlimited.', '+1 to strike.', 'Turret rotates 180 degrees, barrel raises 90 degrees; typically controlled by driver or co-pilot.'),
('wr-5054-mini-cargo-hauler-apc', 1, 'Standard Weapon: Forward Laser Turret', 'Same as the Super, WR-5050: 3D6 M.D. per single blast.', 1, '2000 feet (610 m), per the Super statistics', 'Equal to the gunner hand to hand attacks per melee round, usually 3 to 6, per the Super statistics', 'Effectively unlimited, per the Super statistics', '+1 to strike, per the Super statistics', 'Text says Same as the Super rather than repeating full stats.');

-- Read the result back rather than trusting the exit code. INSERT OR IGNORE
